import{_ as s,C as i,o as e,c as n,a2 as t,b as l,w as r,a as d,E as p,a3 as c}from"./chunks/framework.DToEn73J.js";const f=JSON.parse('{"title":"Guardrails 护栏","description":"","frontmatter":{"title":"Guardrails 护栏","chapter":"5.3","order":3,"summary":"用输入/输出过滤 + 行为限制三层护栏，对高风险操作显式拦截。"},"headers":[],"relativePath":"05-safety-governance/guardrails.md","filePath":"05-safety-governance/guardrails.md","lastUpdated":1787724133000}'),h={name:"05-safety-governance/guardrails.md"};function u(g,a,E,A,B,m){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t(`<h1 id="guardrails-护栏" tabindex="-1">Guardrails 护栏 <a class="header-anchor" href="#guardrails-护栏" aria-label="Permalink to &quot;Guardrails 护栏&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>Guardrails 是在 Agent Loop 外围设置的可编程约束层，确保内容合规、行为受控。它不依赖模型自觉，而是以规则/分类器强制执行。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>三类 Guardrails</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>作用点</th><th>典型实现</th></tr></thead><tbody><tr><td>输入过滤</td><td>进入推理前</td><td>敏感词、PII、注入关键词扫描</td></tr><tr><td>输出过滤</td><td>生成回答后</td><td>泄露检测、毒性分类、格式校验</td></tr><tr><td>行为限制</td><td>Tool 调用前</td><td>白名单、参数边界、频次配额</td></tr></tbody></table><p><strong>高风险操作拦截清单</strong>（命中即阻断或转人工）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 文件系统: 写 /etc、~/.*、delete(recursive=true)</span></span>
<span class="line"><span>- 网络: 外发 HTTP 含凭证头、非白名单域名</span></span>
<span class="line"><span>- 系统: exec/sh、sudo、kill</span></span>
<span class="line"><span>- 数据: 批量导出 &gt; N 行、写生产 DB</span></span>
<span class="line"><span>- 通信: 对外邮件/消息、支付/转账</span></span></code></pre></div><p>最小实现：在 Orchestrator 调度 Tool 前插入 <code>guardrail.check(tool, args)</code>，返回 <code>allow|deny|review</code> 三态。</p>`,9)),(e(),l(c,null,{default:r(()=>[p(o,{id:"mermaid-72",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20U%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%5D%20--%3E%20I%5B%E8%BE%93%E5%85%A5%E8%BF%87%E6%BB%A4%5D%0A%20%20%20%20I%20--%3E%20L%5BAgent%20Loop%5D%0A%20%20%20%20L%20--%3E%20B%5B%E8%A1%8C%E4%B8%BA%E9%99%90%E5%88%B6%3A%20Tool%20%E6%A0%A1%E9%AA%8C%5D%0A%20%20%20%20B%20--%3E%7Callow%7C%20T%5B%E6%89%A7%E8%A1%8C%20Tool%5D%0A%20%20%20%20B%20--%3E%7Creview%7C%20H%5B%E4%BA%BA%E5%B7%A5%E5%AE%A1%E6%89%B9%5D%0A%20%20%20%20L%20--%3E%20O%5B%E8%BE%93%E5%87%BA%E8%BF%87%E6%BB%A4%5D%0A%20%20%20%20O%20--%3E%20R%5B%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>仅凭系统 prompt 要求&quot;不要做 X&quot;不可靠，模型在长上下文或多轮压力下会偏离。Guardrails 把安全从&quot;建议&quot;变成&quot;强制&quot;。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只在输出侧加护栏，忽略 Tool 调用这一真正副作用出口。</li><li>拦截过宽导致正常任务频繁 <code>review</code>，最终被运维绕过。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>Anthropic 安全文档</strong>：建议将护栏与权限模型结合，对高影响动作强制 review。</li><li><strong>OpenAI Agents SDK</strong>：提供 <code>InputGuardrail</code> / <code>OutputGuardrail</code> 钩子，trip 时中断整轮运行。</li><li>参考：<a href="https://openai.github.io/openai-agents-python/guardrails/" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/guardrails/</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/05-safety-governance/prompt-injection">/05-safety-governance/prompt-injection</a></li><li><a href="/fk-ai-agent/02-capability-extension/permission-sandbox">/02-capability-extension/permission-sandbox</a></li><li><a href="/fk-ai-agent/05-safety-governance/kill-switch">/05-safety-governance/kill-switch</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',10))])}const _=s(h,[["render",u]]);export{f as __pageData,_ as default};
